<script setup>import{ref,onMounted,computed}from'vue';import{api}from'../api';const list=ref([]),method=ref(''),status=ref('');onMounted(async()=>list.value=await api.orders());const rows=computed(()=>list.value.filter(x=>(!method.value||x.payMethod===method.value)&&(!status.value||String(x.payStatus)===status.value)));async function exportCsv(){const r=await fetch('/api/admin/orders/export',{headers:{Authorization:`Bearer ${localStorage.getItem('admin_token')}`}});if(!r.ok)throw new Error('导出失败');const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='orders.csv';a.click();URL.revokeObjectURL(a.href)}</script>
<template><div class="page-head"><div><h2>订单管理</h2><p>微信支付与现金发卡统一对账，销售额按实收统计</p></div><el-button @click="exportCsv">导出 CSV</el-button></div><div class="panel"><div class="toolbar"><el-select v-model="method" placeholder="支付方式" clearable style="width:150px"><el-option label="微信支付" value="wechat"/><el-option label="现金" value="cash"/></el-select><el-select v-model="status" placeholder="状态" clearable style="width:150px"><el-option label="待支付" value="0"/><el-option label="已支付" value="1"/><el-option label="已关闭" value="2"/></el-select></div><el-table :data="rows"><el-table-column prop="orderNo" label="订单号" min-width="230"/><el-table-column prop="item.name" label="卡商品"/><el-table-column prop="memberId" label="会员 ID"/><el-table-column label="应付/实收"><template #default="{row}"><b>¥{{row.payableAmount}}</b><div class="price">实收 ¥{{row.paidAmount??'—'}}</div></template></el-table-column><el-table-column label="方式"><template #default="{row}">{{row.payMethod==='cash'?'现金':'微信支付'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.payStatus===1?'success':row.payStatus===2?'info':'warning'">{{['待支付','已支付','已关闭'][row.payStatus]}}</el-tag></template></el-table-column><el-table-column prop="paidAt" label="支付时间" min-width="180"/></el-table></div></template>
